/* Five doors, sized by what each one opens rather than by arithmetic.

   A tier is a claim about what you can now do, so its boundary belongs where
   the ability changes, not every sixty characters. That makes them uneven —
   81, 65, 41, 71, 42 — and uneven is correct: the first door is wide because
   nothing useful happens until greetings, numbers, food and directions are all
   in place, and the third is narrow because money, measure words and the body
   are one short errand's worth of language. */
const TIERS = [
  {n:1, icon:"🥢", name:"Getting by",  zh:"過日辰", to:81,
   blurb:"Enough to greet someone, count, order food and say where you're going."},
  {n:2, icon:"🗣️", name:"Holding up",  zh:"傾得",   to:146,
   blurb:"Time, family, the everyday verbs, and the particles that make you sound like a person rather than a phrasebook."},
  {n:3, icon:"🧾", name:"Handling it", zh:"搞得掂", to:187,
   blurb:"Prices, change, measure words and the body — enough to shop, pay, and say what hurts."},
  {n:4, icon:"🏙️", name:"Living here", zh:"住得慣", to:258,
   blurb:"Weather, the flat, the market, work and the MTR: the vocabulary of an ordinary Hong Kong week."},
  {n:5, icon:"💭", name:"Saying what you mean", zh:"講得出", to:300,
   blurb:"Opinions, feelings, and the connectives that let you give a reason instead of a list."}
];

const TIER_UNLOCK = 0.8;

HQ.forEach((ch, i) => {
  ch.i = i;
  ch.stage = STAGES.find(s => i < s.end).n;
});

const CHAR_INDEX = {};
HQ.forEach(ch => { CHAR_INDEX[ch.c] = ch; });

/* Component families — derived, so adding characters extends the trees for free. */
const FAMILIES = {};
HQ.forEach(ch => {
  ch.comp.forEach(k => {
    if (!FAMILIES[k]) FAMILIES[k] = [];
    FAMILIES[k].push(ch.c);
  });
});

