/* Every distinct character the quest covers, derived from the menu above so
   editing it keeps the quest honest. Characters actually PRINTED on the menu
   come first: learning one should visibly light up a dish, not a phrase you
   can't see. Ordering-phrase characters follow, each tier in teaching order. */
const MENU_CHARS = (() => {
  const printed = new Set(), spoken = new Set();
  const add = (str, set) => [...str].forEach(c => { if (/[一-鿿]/.test(c)) set.add(c); });
  add(MENU.title, printed); add(MENU.name, printed);
  MENU.sections.forEach(s => { add(s.head, printed); s.items.forEach(i => add(i[0], printed)); });
  /* The descriptions and the set-lunch board are printed too — they arrive at
     menu tiers 2 and 3 rather than on day one, but they are on the wall, and a
     character you can read there should count towards reading the menu. */
  MENU.sections.forEach(s => s.items.forEach(i => { if (i[4]) add(i[4][0], spoken); }));
  MENU.specials.items.forEach(i => add(i[0], spoken));
  add(MENU.specials.head, spoken); add(MENU.specials.note[0], spoken);
  MENU.phrases.forEach(p => add(p[0], spoken));
  return HQ.filter(ch => printed.has(ch.c) || spoken.has(ch.c))
           .map((ch, n) => ({ c: ch.c, tier: printed.has(ch.c) ? 0 : 1, n }))
           .sort((a, b) => a.tier - b.tier || a.n - b.n)
           .map(x => x.c);
})();

/* ---------- what is actually on the wall, level by level ----------

   The card is not all printed at once. renderMenuCard shows the masthead and
   the dish names from the start, a dish's small print from level 2, and the
   set-lunch board from level 3 — so "on the menu" is a different set of
   characters depending on how far you have got.

   Two things went wrong for want of saying that out loud:

   The daily pick walked a reading order that included the set-lunch board, and
   included it FIRST, because the board is printed above the sections. So the
   ninth character the quest ever offered was 快 — which appears nowhere except
   that board — above a menu that did not contain it, under the words "find it
   on the menu below". It was findable on nobody's screen until level 3.

   And the progress bar counted MENU_CHARS, which also holds the eight
   characters that appear only in the phrases you say to a waiter: 我 該 個 呀
   幾 碗 呢 埋. All eight are taught in the first four stages, so they arrived
   pre-ticked and the bar read half full while the dishes were still opaque.

   MENU_READ[n] is what is printed at level n, in the order your eye meets it
   going down the card; MENU_LEVELS[n] is the same thing as a set. Both are
   derived from MENU, so editing the menu keeps them honest, and both are
   restricted to taught characters — the quest cannot offer to teach a
   character the library has no card for. */
const MENU_READ = [], MENU_LEVELS = [];
(() => {
  const cjk = str => [...String(str)].filter(c => /[一-鿿]/.test(c));
  const taught = new Set(HQ.map(ch => ch.c));
  const readAt = lvl => {
    const seen = [];
    const add = str => cjk(str).forEach(c => {
      if (taught.has(c) && !seen.includes(c)) seen.push(c);
    });
    add(MENU.title); add(MENU.name);
    /* the set-lunch board sits above the sections on the card, and arrives last */
    if (lvl >= 3) {
      add(MENU.specials.head);
      MENU.specials.items.forEach(i => add(i[0]));
      add(MENU.specials.note[0]);
    }
    MENU.sections.forEach(sec => {
      add(sec.head);
      sec.items.forEach(i => { add(i[0]); if (lvl >= 2 && i[4]) add(i[4][0]); });
    });
    return seen;
  };
  for (let n = 1; n <= 3; n++) { MENU_READ[n] = readAt(n); MENU_LEVELS[n] = new Set(MENU_READ[n]); }
})();

/* Everything the card ever prints — the quest's denominator, and a stable one:
   it does not shrink and grow underneath the learner as levels arrive. What
   DOES depend on the level is which of these the daily pick may choose from,
   which is MENU_READ[level]. */
const MENU_PRINTED = MENU_READ[3];

/* Kept as a name because the rest of the app reads it: the full card in the
   order you read it. Identical to MENU_PRINTED now that both are derived from
   the same walk — the old MENU_ORDER existed only to correct MENU_PRINTED's
   curriculum ordering. */
const MENU_ORDER = MENU_READ[3];

/* How grown-up a menu you get handed, and when.

   Three rules have been tried here. The first gated on menu characters alone,
   and menu characters bunch — you learn eight of them in the Eating stage — so
   the whole menu went from dish names to set lunches inside a week while the
   learner could read a quarter of it. The second added an overall-total gate
   for pacing, which fixed the bunching and introduced a worse problem: the
   menu grew because of characters learned on the Today tab, so it could get
   longer while the dishes in front of you were still unreadable. "It grows to
   with what the waiter says after 3 more characters overall" is a promise that
   the menu will get harder for reasons having nothing to do with the menu.

   The rule now is the obvious one, and it should have been the rule first:
   **you get the next menu when you can read this one.** Every character
   printed at your level, all of them, and then the card grows.

   It cannot strand anybody. MENU_READ only holds characters the library
   teaches, and the quest teaches one a day from the level you are on — so the
   worst case is 23 days to clear level 1, and every one of those days moves
   you one character closer. The gate is entirely in the learner's hands, which
   is the other thing the overall-total gate could not claim. */
const MENU_TIERS = [
  { n: 1, label: "Dish names only" },
  { n: 2, label: "With what the waiter says" },
  { n: 3, label: "Full menu, set lunches and all" }
];

